import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('sums token fields when both operands are defined', () => {
    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
  });

  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });

  it('returns undefined when both operands are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });
});
import type {Message, MessageChunk, ToolCall, UsageMetadata} from '../types/ai.js';
import type {ToolRegistry} from './tools/registry.js';

export function shouldContinueToolLoop(
  stopReason: string,
  pendingToolCalls: ToolCall[],
  toolRegistry: ToolRegistry | undefined
): boolean {
  return stopReason === 'tool_use' && pendingToolCalls.length > 0 && toolRegistry !== undefined;
}

export async function collectText(stream: AsyncGenerator<MessageChunk>): Promise<string> {
  let text = '';
  for await (const chunk of stream) {
    if (chunk.type === 'text') text += chunk.text;
  }
  return text;
}

export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
  return {
    role: 'assistant',
    content: pendingToolCalls.map(tc => ({
      type: 'tool_use' as const,
      toolUseId: tc.id,
      name: tc.name,
      input: tc.input,
    })),
  };
}

export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
}

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

export function accumulateUsage(
  accumulated: UsageMetadata | undefined,
  next: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (accumulated === undefined) return next;
  if (next === undefined) return accumulated;
  return {
    inputTokens: accumulated.inputTokens + next.inputTokens,
    outputTokens: accumulated.outputTokens + next.outputTokens,
    totalTokens: accumulated.totalTokens + next.totalTokens,
  };
}
adrs/ADR-007-repository-visibility.md:20:This package has never been published. The release workflow T011 adds authenticates to the registry through npm trusted publishing over OIDC, which mints a short-lived token from the GitHub Actions identity and stores no secret in the repository. That mechanism is indifferent to visibility: it works from a public, internal or private repository, needing only npm 11.5.1 or newer and `id-token: write` on the publishing job.
adrs/ADR-007-repository-visibility.md:39:One trap in taking that measurement, found while taking it. A `url.git@github.com:.insteadof https://github.com` entry in a developer's git config rewrites the HTTPS URL to SSH before it leaves the machine, so `git ls-remote https://…` succeeds on an unreadable repository and appears to prove the opposite of the truth. The unauthenticated API call has no such rewrite and is the check to trust. So the two are separable: tokenless publishing is available now, and provenance is available only at the cost of visibility. The release workflow therefore either carries the flag or it does not, and cannot be finished until that is settled.
adrs/ADR-007-repository-visibility.md:50:- A package whose source genuinely cannot be public is still published tokenlessly over OIDC, without `--provenance`, and its README says so rather than leaving a consumer to notice the missing attestation.
adrs/ADR-007-repository-visibility.md:72:Against that cost, provenance buys a consumer something they cannot otherwise get: a verifiable claim that a given version was built from a named commit by a named workflow, rather than uploaded by whoever held a token. For a package that executes user input against third-party model APIs, that is worth more than the privacy of a history which the audit shows contains nothing private.
adrs/ADR-007-repository-visibility.md:79:- A pull request from a fork receives no repository secrets and a read-only token whatever a workflow's `permissions` block requests. The workflows already account for this; a contributor-facing note is T033's.
adrs/ADR-007-repository-visibility.md:86:**Stay internal and publish tokenlessly without provenance.** Rejected, but it is the strongest alternative and would have been correct if the audit had gone differently. It costs nothing: trusted publishing needs no visibility, the package is identical, and the only loss is the attestation. It was rejected because the history holds nothing worth protecting, so the privacy being bought is nominal while the verifiability being given up is not.
adrs/ADR-001-bedrock-converse-api.md:46:- `docs/spikes/spike-bedrock-integration.md` — the full spike, including the comparison table, token limits per model, cost analysis and risk assessment. This ADR summarises its decision; the spike remains the record.
